using System;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Linq;using System.Xml;using System.Windows.Forms;
namespace BeamScheduleFormatter {
static class RoofProfileLibrary {
 internal static string DefaultPath{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DTCE Tool Kit","Profiles","RoofProfiles.xml");}}
 static void Validate(List<RoofProfile> profiles){if(profiles.Count==0||profiles.Count>10000)throw new Exception("Save 1 to 10000 valid roof profile options.");var keys=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var profile in profiles){SteelWeight.Positive(profile.Width,profile.Cover);if(string.IsNullOrWhiteSpace(profile.Name)||string.IsNullOrWhiteSpace(profile.SideLap)||profile.Cover>profile.Width||!new[]{"Longspan Rib","Longspan Corrugated"}.Contains(profile.Family)||!keys.Add(profile.Name+"|"+profile.SideLap))throw new Exception("Invalid or duplicate roof profile option.");}foreach(var group in profiles.GroupBy(p=>p.Name,StringComparer.OrdinalIgnoreCase))if(group.Any(p=>p.Family!=group.First().Family||Math.Abs(p.Width-group.First().Width)>1e-8))throw new Exception("Profile options must share a family and full width.");}
 internal static void Save(string path,IEnumerable<RoofProfile> data){var profiles=data.ToList();Validate(profiles);var doc=new XmlDocument();var root=doc.CreateElement("RoofProfileLibrary");root.SetAttribute("version","1");doc.AppendChild(root);foreach(var profile in profiles){var row=doc.CreateElement("Profile");row.SetAttribute("name",profile.Name);row.SetAttribute("family",profile.Family);row.SetAttribute("lap",profile.SideLap);row.SetAttribute("width",profile.Width.ToString("R",CultureInfo.InvariantCulture));row.SetAttribute("cover",profile.Cover.ToString("R",CultureInfo.InvariantCulture));root.AppendChild(row);}string full=Path.GetFullPath(path);Directory.CreateDirectory(Path.GetDirectoryName(full));string temp=full+"."+Guid.NewGuid().ToString("N")+".tmp";try{doc.Save(temp);if(File.Exists(full))File.Replace(temp,full,null);else File.Move(temp,full);}finally{if(File.Exists(temp))File.Delete(temp);}}
 internal static List<RoofProfile> Load(string path){var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(path,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=4000000}))doc.Load(reader);if(doc.DocumentElement.Name!="RoofProfileLibrary"||doc.DocumentElement.GetAttribute("version")!="1")throw new Exception("Unsupported app profile library.");var profiles=new List<RoofProfile>();foreach(XmlElement row in doc.DocumentElement.SelectNodes("Profile"))profiles.Add(new RoofProfile{Name=row.GetAttribute("name"),Family=row.GetAttribute("family"),SideLap=row.GetAttribute("lap"),Width=double.Parse(row.GetAttribute("width"),CultureInfo.InvariantCulture),Cover=double.Parse(row.GetAttribute("cover"),CultureInfo.InvariantCulture)});Validate(profiles);return profiles;}
}
partial class ProgramOfWorksForm {
 Label roofLibraryStatus;
 void SetupRoofProfileLibrary(){var page=tabs.TabPages.Cast<TabPage>().Single(p=>p.Text=="Roofing Start");var tools=page.Controls.OfType<FlowLayoutPanel>().First();Button(tools,"Save profiles in app",()=>SaveRoofProfileLibrary(true));roofLibraryStatus=new Label{AutoSize=true,Padding=new Padding(8,8,0,0),Text="Project profiles are embedded in Excel; save app profiles to reuse in new projects."};tools.Controls.Add(roofLibraryStatus);
  if(File.Exists(RoofProfileLibrary.DefaultPath))try{var profiles=RoofProfileLibrary.Load(RoofProfileLibrary.DefaultPath);bool previous=filling;filling=true;try{roofProfiles.Rows.Clear();foreach(var profile in profiles)roofProfiles.Rows.Add(profile.Name,profile.Family,(profile.Width*1000).ToString("R",CultureInfo.InvariantCulture),profile.SideLap,(profile.Cover*1000).ToString("R",CultureInfo.InvariantCulture));}finally{filling=previous;}roofLibraryStatus.Text="App profile library loaded. Excel-linked projects keep their own saved profile settings.";}catch(Exception ex){roofLibraryStatus.Text="App profiles unavailable: "+ex.Message;}
  roofProfiles.CellEndEdit+=(s,e)=>{if(!filling)SaveRoofProfileLibrary(false);};
 }
 void SaveRoofProfileLibrary(bool explicitSave){Recalculate();bool valid=savedRoofProfiles.Count>0&&!roofProfiles.Rows.Cast<DataGridViewRow>().Any(row=>!row.IsNewRow&&!Empty(row)&&Cell(row,5)!="Saved in project");if(!valid){roofLibraryStatus.Text="Complete valid profile rows before saving to the app library.";if(explicitSave)throw new Exception(roofLibraryStatus.Text);return;}try{RoofProfileLibrary.Save(RoofProfileLibrary.DefaultPath,savedRoofProfiles);roofLibraryStatus.Text="Profiles saved in this app. Active estimate/DXF data stays embedded in the linked Excel file.";}catch(Exception ex){roofLibraryStatus.Text="App profile save failed: "+ex.Message;if(explicitSave)throw;}}
}
}
